import React from 'react';

interface HeroStat {
    readonly value: string;
    readonly label: string;
}

// Compile-time static constants out of the component scope to save runtime memory
const HERO_STATS: readonly HeroStat[] = [
    { value: '03+', label: 'Projects Completed' },
    { value: '04', label: 'Core Framework Skills' },
    { value: '∞', label: 'Continuous Curiosity' },
] as const;

const CARD_SKILLS: readonly string[] = ['HTML', 'CSS', 'JS'] as const;
export default function Hero(): React.JSX.Element {
    return (
        <section className="hero section" id="home" aria-labelledby="hero-title">
            <div className="hero-background" aria-hidden="true">
                <div className="hero-grid" />
                <div className="hero-glow hero-glow-one" />
                <div className="hero-glow hero-glow-two" />
            </div>

            <div className="container hero-container">
                <div className="hero-content">
                    <h2 className="eyebrow" data-reveal="lazy">FRONTEND DEVELOPER</h2>
                    <h1 className="hero-title" id="hero-title" data-reveal="critical">
                        Building <span className="accent-text">digital experiences</span> that matter.
                    </h1>
                    <p className="hero-description" data-reveal="critical">
                        I'm Rayyan Khan, a frontend developer focused
                        on creating fast, responsive, and thoughtfully
                        designed experiences for the web.
                    </p>

                    <div className="hero-actions" role='list'>
                        <a className="button button-primary" href="#work" aria-label="View Rayyan Khan's portfolio projects">
                            View my work
                            <span className="button-arrow" aria-hidden="true">→</span>
                        </a>
                        <a className="button button-secondary" href="#contact" aria-label="Navigate to contact form to hire Rayyan Khan">
                            Let's talk
                        </a>
                    </div>

                    <div className="hero-stats" role='list'>
                        {HERO_STATS.map((stat, idx) => (
                            <div key={idx} className="stat">
                                <strong className="stat-value">{stat.value}</strong>
                                <span className="stat-label">{stat.label}</span>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="hero-visual" aria-hidden="true">
                    <div className="hero-card">
                        <div className="hero-card-top">
                            <span className="window-dot" />
                            <span className="window-dot" />
                            <span className="window-dot" />
                        </div>
                        <div className="hero-letter">R</div>
                        <div className="hero-card-bottom">
                            {CARD_SKILLS.map((skill, idx) => (
                                <span key={idx} className="skill-tag">{skill}</span>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            <a className="scroll-indicator" href="#work" aria-label="Scroll down to projects section">
                <span className="scroll-text">Scroll</span>
                <span className="scroll-line" aria-hidden="true" />
            </a>
        </section>
    );
}