import { CONFIG } from "../core/config.ts";

export default class Theme {
    // Private encapsulation shields internal state from outer global scopes
    #root = document.documentElement;
    #toggleButton = document.getElementById('theme-toggle');
    #iconEl = this.#toggleButton?.querySelector('.theme-icon');
    #headerEl = document.querySelector('header') || document.getElementById('header'); // Header pointer
    #storageKey = CONFIG.STORAGE_THEME_KEY || '__portfolio_theme__';
    #currentActiveTheme = null;

    constructor() {
        this.#initialize();
        this.#setupEventListeners();
    }

    #initialize() {
        const savedTheme = this.#getValidatedStorage();
        if (savedTheme) {
            this.#setTheme(savedTheme, false);
            return;
        }

        const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
        this.#setTheme(prefersDark ? "dark" : "light", true);
    }

    #setupEventListeners() {
        if (!this.#toggleButton) return;
        
        this.#toggleButton.addEventListener('click', () => this.toggleTheme());

        // Instant OS-level change synchronization
        window.matchMedia("(prefers-color-scheme: dark)")
            .addEventListener('change', (e) => {
                if (!localStorage.getItem(this.#storageKey)) {
                    this.#setTheme(e.matches ? "dark" : "light", false);
                }
            });
    }

    #getValidatedStorage() {
        try {
            const val = localStorage.getItem(this.#storageKey);
            return (val === 'dark' || val === 'light') ? val : null;
        } catch (e) {
            console.warn("Storage access denied. Falling back to system defaults.");
            return null;
        }
    }

    #setTheme(theme, shouldSave = true) {
        if (this.#currentActiveTheme === theme) return;
        this.#currentActiveTheme = theme;

        requestAnimationFrame(() => {
            this.#root.dataset.theme = theme;
            this.#root.style.colorScheme = theme; 

            if (shouldSave) {
                try {
                    localStorage.setItem(this.#storageKey, theme);
                } catch (e) { /* Fail silently if private browsing prevents saving */ }
            }

            if (this.#toggleButton) {
                this.#toggleButton.setAttribute('aria-pressed', String(theme === 'dark'));
            }

            if (this.#iconEl) {
                this.#iconEl.textContent = theme === 'dark' ? '🌙' : '☀';
            }

            if (this.#headerEl) {
                if (theme === 'dark') {
                    this.#headerEl.classList.add('header-dark');
                    this.#headerEl.classList.remove('header-light');
                    this.#headerEl.setAttribute('data-theme', 'dark');
                } else {
                    this.#headerEl.classList.add('header-light');
                    this.#headerEl.classList.remove('header-dark');
                    this.#headerEl.setAttribute('data-theme', 'light');
                }
            }

            const metaThemeColor = document.querySelector('meta[name="theme-color"]');
            if (metaThemeColor) {
                const fallbackColor = theme === 'dark' ? '#0d0d0d' : '#ef476f';
                metaThemeColor.setAttribute('content', fallbackColor);
            }
        });
    }

    toggleTheme() {
        const current = this.#currentActiveTheme || "light";
        this.#setTheme(current === "dark" ? "light" : "dark", true);
    }
}