import React, { useState, useEffect, useCallback, useRef } from 'react';

const NAV_ITEMS = [
    { id: 'home', label: 'Home' },
    { id: 'work', label: 'Work' },
    { id: 'features', label: 'Features' },
    { id: 'about', label: 'About' },
    { id: 'skills', label: 'Skills' },
    { id: 'contact', label: 'Contact' },
] as const; // "as const" makes values Readonly Literals rather than loose strings

type SectionId = typeof NAV_ITEMS[number]['id'];
type ThemeMode = 'dark' | 'light';

export default function Header(): React.JSX.Element {
    const [isMenuOpen, setIsMenuOpen] = useState<boolean>(false);
    const [activeSection, setActiveSection] = useState<SectionId>('home');
    
    // Type-safe reference to the menu trigger button for focus management
    const menuToggleRef = useRef<HTMLButtonElement | null>(null);
    const [theme, setTheme] = useState<ThemeMode>((): ThemeMode => {
        if (typeof window !== 'undefined') {
            const saved = localStorage.getItem('theme') as ThemeMode | null;
            if (saved === 'dark' || saved === 'light') return saved;
            
            const matchesDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
            return matchesDark ? 'dark' : 'light';
        }
        return 'light';
    });

    useEffect(() => {
        const root: HTMLElement = document.documentElement;
        const themeClass: `${ThemeMode}-theme` = `${theme}-theme`;
        const oppositeClass: `${ThemeMode}-theme` = theme === 'dark' ? 'light-theme' : 'dark-theme';

        root.classList.add(themeClass);
        root.classList.remove(oppositeClass);
        localStorage.setItem('theme', theme);
    }, [theme]);

    const toggleMenu = useCallback((): void => setIsMenuOpen((prev) => !prev), []);
    const toggleTheme = useCallback((): void => {
        setTheme((prev) => (prev === 'dark'? 'light':'dark'));
    }, []);
    
    const handleCommandPalette = useCallback((): void => {
        console.log('Command palette toggled');
    }, []);

    useEffect(() => {
        const handleScroll = (): void => {
            const scrollPosition: number = window.scrollY + 160; 
            for (const item of NAV_ITEMS) {
                const element: HTMLElement | null = document.getElementById(item.id);
                if (element) {
                    const offsetTop: number = element.offsetTop;
                    const offsetHeight: number = element.offsetHeight;
                    if (scrollPosition >= offsetTop && scrollPosition < offsetTop + offsetHeight) {
                        setActiveSection(item.id);
                        break;
                    }
                }
            }
        };

        window.addEventListener('scroll', handleScroll, { passive: true });
        return (): void => window.removeEventListener('scroll', handleScroll);
    }, []);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent): void => {
            if (e.key === 'Escape' && isMenuOpen) {
                setIsMenuOpen(false);
                menuToggleRef.current?.focus();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return (): void => window.removeEventListener('keydown', handleKeyDown);
    }, [isMenuOpen]);

    useEffect(() => {
        document.body.style.overflow = isMenuOpen ? 'hidden' : 'unset';
    }, [isMenuOpen]);

    return (
        <header className="site-header" id="site-header">
            <nav className="navbar container" aria-label="Primary site navigation">
                <a className="logo" href="#home" aria-label="Rayyan Khan Home Page">
                    <span className="logo-mark" aria-hidden="true">R</span>\
                    <span className="logo-text">Rayyan</span>
                </a>

                <div 
                    className={`nav-wrapper ${isMenuOpen ? 'is-active':''}`} 
                    id="navigation-menu"
                    role="dialog" 
                    aria-modal={isMenuOpen}
                    aria-label="Navigation Links"
                >
                    <ul className="nav-list">
                        {NAV_ITEMS.map((item) => (
                            <li key={item.id}>
                                <a 
                                    className={`nav-link ${activeSection === item.id? 'active':''}`} 
                                    href={`#${item.id}`}
                                    data-section={item.id}
                                    aria-current={activeSection === item.id? 'page':undefined}
                                    onClick={(): void => setIsMenuOpen(false)}
                                >
                                    {item.label}
                                </a>
                            </li>
                        ))}
                    </ul>
                </div>

                <div className="nav-actions">
                    <button 
                        className="theme-toggle" 
                        id="theme-toggle" 
                        type="button" 
                        aria-label={theme === 'dark' ? "Switch to light theme" : "Switch to dark theme"} 
                        aria-pressed={theme === 'dark'}
                        onClick={toggleTheme}
                    >
                        <span className="theme-icon" aria-hidden="true">◐</span>
                    </button>

                    <button 
                        className="command-toggle" 
                        id="command-toggle" 
                        type="button" 
                        aria-label="Open command palette shortcut" 
                        aria-haspopup="dialog"
                        onClick={handleCommandPalette}
                    >
                        <span className="command-icon" aria-hidden="true">⌘</span>
                    </button>

                    <button 
                        ref={menuToggleRef} // Uses React memory ref instead of string DOM queries
                        className={`menu-toggle ${isMenuOpen ? 'open':''}`} 
                        id="menu-toggle" 
                        type="button" 
                        aria-label={isMenuOpen? "Close main navigation menu":"Open main navigation menu"} 
                        aria-controls="navigation-menu" 
                        aria-expanded={isMenuOpen}
                        onClick={toggleMenu}
                    >
                        <span aria-hidden="true"></span>
                        <span aria-hidden="true"></span>
                        <span aria-hidden="true"></span>
                    </button>
                </div>
                
            </nav>
        </header>
    );
}