export const $ = <T extends Element = Element>(selector: string,  parent: ParentNode = document): T | null => 
    parent.querySelector(selector) as T | null;

export const $$ = <T extends Element = Element>(selector: string, parent: ParentNode = document): T[] =>
    Array.prototype.slice.call(parent.querySelectorAll(selector)) as T[];

export const clamp = (value: number, min: number, max: number): number => {
    const t = value < min ? min : value;
    return t > max ? max : t;
};

export const win: Window = window;
export const mobileQuery: MediaQueryList = win.matchMedia("(max-width: 850px)");
export const motionQuery: MediaQueryList = win.matchMedia("(prefers-reduced-motion: reduce)");

export const isMobile = (): boolean => mobileQuery.matches;
export const prefersReducedMotion = (): boolean => motionQuery.matches;

let framePromise: Promise<void> | null = null;
export const nextFrame = (): Promise<void> => 
    framePromise || (framePromise = new Promise((r) => 
        requestAnimationFrame(() => { framePromise = null; r(); })
    ));

export const rafThrottle = <T extends (...args: any[]) => void>(callback: T) => {
    let ticking: 0|1 = 0; // Uses fast SMI (Small Integer) instead of booleans
    let savedArgs: Parameters<T>;
    let savedThis: unknown;
    const run = () => {
        ticking = 0;
        callback.apply(savedThis, savedArgs);
    };
    return function (this: unknown, ...args: Parameters<T>): void {
        savedArgs = args;
        savedThis = this;
        if (ticking) return;
        ticking = 1;
        requestAnimationFrame(run);
    };
};

export const debounce = <T extends (...args: any[]) => void>(callback: T, delay: number = 100) => {
    let timeout: NodeJS.Timeout; // Fast primitive tracker
    let savedArgs: Parameters<T>;
    let savedThis: unknown;
    const run = (): void => {
        callback.apply(savedThis, savedArgs);
    };
    return function (this: unknown, ...args: Parameters<T>): void {
        savedArgs = args;
        savedThis = this;
        clearTimeout(timeout);
        timeout = setTimeout(run, delay);
    };
};