import { StrictMode } from 'react';
import { createRoot, Root } from 'react-dom/client';
import App from './App.tsx';

// Locate the mounting root node inside the real DOM infrastructure
const rootElement: HTMLElement | null = document.getElementById('root');
// Defensive Guardrail: Prevent runtime application breakdown if the DOM node isn't mounted yet
if (!rootElement) {
    throw new Error(
        "🚨 Critical Initialization Failure: Failed to find target mounting element with ID 'root'. " +
        "Verify that <div id=\"root\"></div> is properly declared inside your public/index.html document."
    );
}

// Instantiate the high-performance concurrent React 18 rendering loop
const root: Root = createRoot(rootElement);
root.render(
    <StrictMode>
        <App />
    </StrictMode>
);

// 🚀 HYPER-ULTRA PROGRESSIVE WEB APP (PWA) SERVICE WORKER ORCHESTRATOR
if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
        // Targets the root path served cleanly out of your public folder build
        navigator.serviceWorker.register('/My_Portfolio/sw.js')
            .then((registration: ServiceWorkerRegistration) => {
                console.log('📡 [PWA] Service Worker active under scope:', registration.scope);
                setInterval(() => {
                    registration.update();
                    console.log('🔄 [PWA] Checking server for portfolio asset updates...');
                }, 60 * 60 * 1000);
                // Listen for a newly installed background worker waiting to take over
                registration.addEventListener('updatefound', () => {
                    const newWorker = registration.installing;
                    if (!newWorker) return;
                    newWorker.addEventListener('statechange', () => {
                        // If a new build finishes installing, immediately swap it and refresh
                        if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                            console.log('✨ [PWA] New version discovered! Refreshing user shell...');
                            window.location.reload();
                        }
                    });
                });
            })
            .catch((error: Error) => {
                console.error('🛑 [PWA] Service Worker initialization failed:', error);
            });
    });
}