import React, { useId, type HTMLAttributes, type FC } from 'react';

export interface ProjectContent {
    heading: string;
    description: string;
}

export interface ProjectItem {
    main: boolean;
    id: number | string;
    preview: readonly [string, string];
    type: string;
    content: ProjectContent;
    category: string;
    tags: readonly string[];
    link: string;
    target: string;
}

export interface ProjectCardProps extends HTMLAttributes<HTMLElement> {
    project: ProjectItem;
}

export interface ProjectGridProps extends HTMLAttributes<HTMLDivElement> {
    projects: readonly ProjectItem[];
    className: string;
}

