export const ProjectCard: FC<ProjectCardProps> = React.memo(({ project, className = "", ...restProps }): React.JSX.Element => {
    const baseId: string = useId();
    const titleId: string = `title-${baseId}`;
    
    const rawPreview = project?.preview;
    const cleanPreview: readonly string[] = Array.isArray(rawPreview) 
        ? rawPreview.map(val => typeof val === 'string'? val : String(val ?? ''))
        : ['', ''];
    const previewText: string = cleanPreview[0] || '';
    const previewIcon: string = cleanPreview[1] || '';
    const hasValidPreview: boolean = (previewText.trim().length > 0 || previewIcon.trim().length > 0);

    const heading: string = project?.content?.heading ?? "Untitled Project";
    const description: string = project?.content?.description ?? "No description available.";
    const tags = project?.tags ?? [];
    const projectLink: string = project?.link ?? "#";
    
    const isLinkActive: boolean = projectLink !== "#" && /^https?:\/\//i.test(projectLink);
    const cardClass: string = `project-card ${project?.main ? 'project-card--main' : ''} ${className}`.trim();
    const isBlank: boolean = project?.target === '_blank';

    return (
        <article id={`card-${project?.id ?? baseId}`} className={cardClass} aria-labelledby={titleId} {...restProps}>
            {/* SAFETY FIX: Conditional layout mounting checks content text length to block blank text nodes from crashing CSS engines */}
            {hasValidPreview && (
                <div className="project-preview">
                    {previewText && <span className="preview-title">{previewText}</span>}
                    {previewIcon && <span className="preview-symbol" aria-hidden="true">{previewIcon}</span>}
                </div>
            )}

            <header className="project-card-header">
                <span className="project-type" role="status">{project?.type ?? 'Project'}</span>
                <h3 id={titleId} className="project-title">{heading}</h3>
            </header>
            
            <p className="project-description">{description}</p>
            
            <footer className="project-footer">
                {tags.length > 0 && (
                    <div className="project-tags" aria-label="Technologies Used">
                        {tags.map((tag) => {
                            if (!tag || typeof tag !== 'string') return null;
                            return <span key={tag} className="project-tag">{tag}</span>;
                        })}
                    </div>
                )}

                {isLinkActive && (
                    <a 
                        href={projectLink} 
                        className="project-link" 
                        target={isBlank ? "_blank" : undefined} 
                        rel={isBlank ? "noopener noreferrer" : undefined}
                    >
                        View Project
                    </a>
                )}
            </footer>
        </article>
    );
});
ProjectCard.displayName = 'ProjectCard';

export const ProjectGrid: FC<ProjectGridProps> = React.memo(({ projects = [], className = "", ...restProps }): React.JSX.Element => {
    return (
        <div className={`project-grid ${className}`.trim()} role="feed" {...restProps}>
            {projects.map((project) => {
                if (!project || typeof project !== 'object' || !project.id) return null;
                return <ProjectCard key={project.id} project={project} />;
            })}
        </div>
    );
});
ProjectGrid.displayName = 'ProjectGrid';