import React, { ElementType, ComponentPropsWithRef, JSX, ReactNode } from 'react';

export type PolymorphicProps<T extends ElementType, Props = {}> = Props & {
    as?: T;
} & Omit<ComponentPropsWithRef<T>, 'as' | keyof Props>;

export interface ContainerProps {
    readonly children: ReactNode;
}
export function Container<T extends ElementType = 'div'>({as, children, ...props}: PolymorphicProps<T, ContainerProps>): JSX.Element {
    const Component: T | 'div' = as || 'div';
    return <Component {...props}>{children}</Component>;
}

export interface HeadingProps {
    readonly level: 1 | 2 | 3 | 4 | 5 | 6;
}

export function Heading<T extends ElementType = 'h1'>({level, as, children, ...props}: PolymorphicProps<T, HeadingProps>): JSX.Element {
    const Component: React.ElementType = as || (`h${level}` as ElementType);
    return <Component {...props}>{children}</Component>;
}

export interface ButtonProps {
    readonly isLoading?: boolean;
    readonly disabled?: boolean;
}

export function Button<T extends ElementType = 'button'>({as, isLoading = false, disabled = false, children, ...props}: PolymorphicProps<T, ButtonProps>): JSX.Element {
    const Component: T | 'button' = as || 'button';
    const isButton: boolean = Component === 'button';

    return (
        <Component
            disabled={isButton? (disabled || isLoading) : undefined}
            aria-disabled={!isButton? (disabled || isLoading) : undefined}
            type={isButton? ((props as any).type || 'button') : undefined}
            {...props}
        >
            {children}
        </Component>
    );
}

export interface LinkProps {
    readonly external?: boolean;
    readonly children: ReactNode;
}

export function Link<T extends ElementType = 'a'>({as, external = false, children, ...props}: PolymorphicProps<T, LinkProps>): JSX.Element {
    const Component: T | 'a' = as || 'a';
    const isAnchor: boolean = Component === 'a';
    const externalProps: Object | {target: string, rel: string} = (isAnchor && external) ? { target: '_blank', rel: 'noopener noreferrer' } : {} as Object;
    return <Component {...externalProps} {...props}>{children}</Component>;
}

export interface InputProps {
    readonly isInvalid?: boolean;
    readonly type?: string;
}

export function Input<T extends ElementType = 'input'>({as, isInvalid = false, ...props}: PolymorphicProps<T, InputProps>): JSX.Element {
    const Component: T | 'input' = as || 'input';
    return (
        <Component 
            aria-invalid={isInvalid || undefined} 
            type={Component === 'input'? ((props as any).type || 'text') : undefined} 
            {...props} 
        />
    );
}

export function Card<T extends ElementType = 'div'>({as, children, ...props}: PolymorphicProps<T>): JSX.Element {
    const Component: T | 'div' = as || 'div';
    return <Component {...props}>{children}</Component>;
}